  "faq.title": "Frequently asked questions",
  "faq.intro": "Quick answers about listing, qualification, and how Flare Registry works.",
  "faq.more": "Still have a question?",
  "faq.q.list": "How do I get listed?",
  "faq.q.qualified": "What does \"Qualified\" mean?",
  "faq.q.notQualified": "Why is my provider not Qualified?",
